with exploded as (select id, host, level, latency_ms, status_code, key, attr_value from app_logs lateral view explode(context) t as key, attr_value), ranked as (select * from (select *, row_number() over (partition by key, level order by status_code desc, id, key) as latest_rank from exploded) t where latest_rank = 1), deduped as (select * from (select *, rank() over (partition by level order by latest_rank desc) as rank_in_group from ranked) t where rank_in_group = 1), latest as (select * from deduped qualify rank() over (partition by level, host order by rank_in_group desc) = 1), scored as (select *, avg(status_code) over (partition by host, level order by rank_in_group, id, key rows between 2 preceding and current row) as status_code_avg_2, ntile(5) over (partition by key order by status_code, id, key) as status_code_bucket from latest), kept_keys as (select id, host from scored intersect select id, host from app_logs where to_date(log_ts) < '2023-07-01'), verified as (select s.* from scored s join kept_keys k on s.id = k.id and s.host = k.host), scored_app_logs as (select id, host, level, latency_ms, status_code, key, attr_value, latest_rank, rank_in_group, status_code_avg_2, status_code_bucket, avg(status_code_bucket) over (partition by level, key) as level_avg_status_code_bucket, dense_rank() over (order by status_code_bucket desc) as status_code_bucket_dense_rank from verified) select id, host, level, key, status_code_avg_2 from scored_app_logs order by status_code_avg_2 desc nulls last, host desc
